import sys
from itertools import product

def main():
    guess, fb = sys.stdin.read().split()[:2]
    absent = {guess[i] for i in range(5) if fb[i] == 'B'}
    digits = '0123456789'
    allowed = []
    for i in range(5):
        if fb[i] == 'G':
            allowed.append([guess[i]] if guess[i] not in absent else [])
        else:
            opts = [d for d in digits if d not in absent]
            if fb[i] == 'Y':
                opts = [d for d in opts if d != guess[i]]
            allowed.append(opts)
    allowed[0] = [d for d in allowed[0] if d != '0']
    yes = [guess[i] for i in range(5) if fb[i] == 'Y']
    res = []
    for combo in product(*allowed):
        if all(d in combo for d in yes):
            res.append(int(''.join(combo)))
    res.sort()
    print(len(res))
    if res:
        print(' '.join(map(str, res)))

